                continue

            link_path = normalize_link(link)
            if not link_path:
                continue

            target_path = (source_file.parent / link_path).resolve()
            if not target_path.exists():
                errors.append(
                    "Broken link in "
                    f"{display_path(source_file)}: {link} -> {display_path(target_path)}"
                )

